"""Install on the assistant server. Does not read or print API keys."""
from pathlib import Path
import ast, getpass, hashlib, json, os, re, secrets, shutil, subprocess
from datetime import datetime
GATE = "# AFIT_ACCESS_GATE_V1 — inserted before the original HTTPServer starts.\nimport base64 as _af_b64\nimport hashlib as _af_hash\nimport hmac as _af_hmac\nimport io as _af_io\nimport re as _af_re\nimport secrets as _af_secrets\nimport sqlite3 as _af_sql\nimport time as _af_time\nfrom http.cookies import SimpleCookie as _AfCookie\nfrom pathlib import Path as _AfPath\n\n_af_config = json.loads(_AfPath('/state/afit_access.json').read_text())\n_af_secret = bytes.fromhex(_af_config['secret'])\n_af_db_path = '/state/afit_access.sqlite'\n\ndef _af_db():\n    db = _af_sql.connect(_af_db_path, timeout=10)\n    db.execute('CREATE TABLE IF NOT EXISTS sessions (id TEXT PRIMARY KEY, used INTEGER NOT NULL DEFAULT 0, member_until INTEGER NOT NULL DEFAULT 0)')\n    db.execute('CREATE TABLE IF NOT EXISTS login_attempts (id INTEGER PRIMARY KEY, sid TEXT NOT NULL, at INTEGER NOT NULL)')\n    return db\n\ndef _af_session(handler):\n    sid = None\n    try:\n        cookie = _AfCookie(handler.headers.get('Cookie', ''))\n        value = cookie['afit_session'].value.split('.')\n        if len(value) == 2 and _af_re.fullmatch(r'[a-f0-9]{48}', value[0]):\n            expected = _af_hmac.new(_af_secret, value[0].encode(), _af_hash.sha256).hexdigest()\n            if _af_hmac.compare_digest(expected, value[1]): sid = value[0]\n    except (KeyError, ValueError, TypeError): pass\n    if sid is None: sid = _af_secrets.token_hex(24)\n    signature = _af_hmac.new(_af_secret, sid.encode(), _af_hash.sha256).hexdigest()\n    handler._af_cookie = 'afit_session='+sid+'.'+signature+'; Path=/; Max-Age=31536000; Secure; HttpOnly; SameSite=Lax'\n    with _af_db() as db:\n        db.execute('INSERT OR IGNORE INTO sessions(id) VALUES (?)', (sid,))\n        row = db.execute('SELECT used, member_until FROM sessions WHERE id=?', (sid,)).fetchone()\n    return sid, row[0], row[1] > int(_af_time.time())\n\n_af_original_end = Handler.end_headers\n_af_original_get = Handler.do_GET\n_af_original_post = Handler.do_POST\n\ndef _af_end(self):\n    if getattr(self, '_af_cookie', None):\n        self.send_header('Set-Cookie', self._af_cookie)\n        self.send_header('Cache-Control', 'no-store')\n    return _af_original_end(self)\n\ndef _af_get(self):\n    if self.path.split('?')[0] != '/session': return _af_original_get(self)\n    try:\n        sid, used, member = _af_session(self)\n        return self.send_json(200, {'remaining': max(0, 30-used), 'member': member, 'limit': 30})\n    except Exception:\n        return self.send_json(503, {'error': 'Не удалось проверить доступ. Попробуйте позже.'})\n\ndef _af_post(self):\n    route = self.path.split('?')[0]\n    if route not in ('/chat', '/member-login'): return _af_original_post(self)\n    origin = self.headers.get('Origin')\n    if origin and origin not in ('https://assistant.alenafit.com', 'https://alenafit.com', 'https://www.alenafit.com'):\n        return self.send_json(403, {'error': 'Недопустимый источник запроса'})\n    if self.headers.get('Content-Type', '').split(';')[0].strip().lower() != 'application/json':\n        return self.send_json(415, {'error': 'Ожидается JSON'})\n    try:\n        size = int(self.headers.get('Content-Length', '0'))\n        if not 0 < size <= 8192: raise ValueError()\n        body = self.rfile.read(size)\n        data = json.loads(body)\n        if not isinstance(data, dict): raise ValueError()\n    except (ValueError, UnicodeDecodeError, TypeError):\n        return self.send_json(400, {'error': 'Некорректный запрос'})\n    try:\n        sid, used, member = _af_session(self)\n        if route == '/member-login':\n            name, password = data.get('login'), data.get('password')\n            now = int(_af_time.time())\n            with _af_db() as db:\n                db.execute('BEGIN IMMEDIATE')\n                db.execute('DELETE FROM login_attempts WHERE at < ?', (now-600,))\n                per_session = db.execute('SELECT COUNT(*) FROM login_attempts WHERE sid=?', (sid,)).fetchone()[0]\n                total = db.execute('SELECT COUNT(*) FROM login_attempts').fetchone()[0]\n                if per_session >= 5 or total >= 30:\n                    return self.send_json(429, {'error': 'Слишком много попыток входа. Повторите через 10 минут.'})\n                db.execute('INSERT INTO login_attempts(sid, at) VALUES (?, ?)', (sid, now))\n            valid_fields = isinstance(name, str) and _af_re.fullmatch(r'[A-Za-z][A-Za-z0-9_-]{0,31}', name) and isinstance(password, str) and 1 <= len(password) <= 128\n            valid_password = False\n            if valid_fields:\n                digest = _af_hash.pbkdf2_hmac('sha256', password.encode(), bytes.fromhex(_af_config['salt']), 260000).hex()\n                valid_password = _af_hmac.compare_digest(digest, _af_config['password_hash'])\n            if not valid_password:\n                return self.send_json(401, {'error': 'Проверьте логин и пароль участника.'})\n            with _af_db() as db:\n                db.execute('UPDATE sessions SET member_until=? WHERE id=?', (now+7*86400, sid))\n            return self.send_json(200, {'member': True})\n        message = data.get('message')\n        if not isinstance(message, str) or not 1 <= len(message.strip()) <= 1500:\n            return self.send_json(400, {'error': 'Введите сообщение до 1500 символов'})\n        if not member:\n            with _af_db() as db:\n                db.execute('BEGIN IMMEDIATE')\n                used = db.execute('SELECT used FROM sessions WHERE id=?', (sid,)).fetchone()[0]\n                if used >= 30:\n                    return self.send_json(401, {'error': 'Для продолжения войдите как участник ALENAFIT.', 'code': 'member_required', 'remaining': 0})\n                db.execute('UPDATE sessions SET used=used+1 WHERE id=?', (sid,))\n    except Exception:\n        return self.send_json(503, {'error': 'Не удалось проверить доступ. Попробуйте позже.'})\n    self.rfile = _af_io.BytesIO(body)\n    return _af_original_post(self)\n\nHandler.end_headers = _af_end\nHandler.do_GET = _af_get\nHandler.do_POST = _af_post\n# AFIT_ACCESS_GATE_END\n"
MEMBER_JS = '// AFIT_MEMBER_UI_V1\nconst memberPanel=document.querySelector(\'#afit-member-panel\');\nconst memberForm=document.querySelector(\'#afit-member-form\');\nconst memberStatus=document.querySelector(\'#afit-member-status\');\nconst quotaNote=document.querySelector(\'#afit-quota\');\nfunction setAccessState(data){\n const locked=!data.member&&data.remaining===0;\n memberPanel.hidden=!locked;\n form.hidden=locked;\n quotaNote.textContent=data.member?\'Доступ участника ALENAFIT\':`Доступно вопросов: ${data.remaining} из 30`;\n if(locked)status.textContent=\'Войдите, чтобы продолжить разговор\';\n}\nasync function refreshAccess(){\n try{const r=await fetch(\'/session\',{cache:\'no-store\'});if(r.ok)setAccessState(await r.json())}catch(e){quotaNote.textContent=\'\'}\n}\nmemberForm.addEventListener(\'submit\',async e=>{\n e.preventDefault();const submit=memberForm.querySelector(\'button\');if(submit.disabled)return;\n submit.disabled=true;memberStatus.textContent=\'Проверяю доступ…\';\n try{\n  const r=await fetch(\'/member-login\',{method:\'POST\',headers:{\'Content-Type\':\'application/json\'},body:JSON.stringify({login:memberForm.elements.login.value.trim(),password:memberForm.elements.password.value})});\n  const d=await r.json();if(!r.ok)throw Error(d.error||\'Не удалось войти\');\n  memberForm.elements.password.value=\'\';setAccessState({member:true,remaining:0});status.textContent=\'Можно продолжать\';input.focus();\n }catch(err){memberStatus.textContent=err.message}\n finally{submit.disabled=false}\n});\nbutton.setAttribute(\'aria-label\',\'Отправить сообщение\');button.title=\'Отправить сообщение\';\nbutton.innerHTML=\'<svg viewBox="0 0 24 24" width="22" height="22" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 19V5M5 12l7-7 7 7"/></svg>\';\nrefreshAccess();\n'
MEMBER_CSS = '<style id="afit-member-composer">\n#form{display:grid;grid-template-columns:minmax(0,1fr) 44px;gap:5px 8px;align-items:end;flex:none;border-top:1px solid #ccd5cd;padding-top:9px}\n#form[hidden],#afit-member-panel[hidden]{display:none!important}\n#question{grid-column:1;grid-row:1;width:100%;height:48px;min-height:48px;max-height:100px;padding:12px;border-radius:18px;resize:none;outline-offset:1px}\n#form .actions{display:contents}#send{grid-column:2;grid-row:1;display:grid;place-items:center;width:44px;height:44px;min-height:44px;padding:0;margin-bottom:2px;border-radius:50%;background:#294d3f;box-shadow:none}\n#status{grid-column:1/-1;grid-row:2;font-size:11px;min-height:15px;margin:0;padding-left:4px}#form>p{display:none}\n#afit-quota{font-size:10px;color:#63736c;margin:3px 0;flex:none}\n#afit-member-panel{flex:none;background:#edf1e8;border-top:1px solid #ccd5cd;padding:12px 0 8px}\n#afit-member-panel h2{font:600 16px/1.3 system-ui,sans-serif;margin:0 0 4px}#afit-member-panel p{font-size:12px;color:#63736c;margin:4px 0 10px}\n#afit-member-form{display:grid;grid-template-columns:1fr 1fr;gap:8px;padding:0;background:transparent;position:static}\n#afit-member-form label{display:grid;gap:3px;font-size:11px;min-width:0}#afit-member-form input{width:100%;min-width:0;padding:10px;border:1px solid #8b9d90;border-radius:10px;font:16px system-ui,sans-serif;background:#fff;color:#263b35}\n#afit-member-form button{grid-column:1/-1;min-height:42px;padding:8px 16px}#afit-member-status{grid-column:1/-1;font-size:11px;color:#63736c}\n@media(max-height:400px){#afit-member-panel{padding:6px 0}#afit-member-panel p{display:none}#afit-member-form{gap:4px}#afit-member-form input{padding:6px}#afit-member-form button{min-height:36px}#question{height:44px;min-height:44px}#afit-quota{margin:0;font-size:9px}}\n</style>\n'
MEMBER_PANEL = '<div id="afit-member-panel" hidden><h2>Вход для участников ALENAFIT</h2><p>Для участников онлайн-сопровождения и занятий в зале.</p><form id="afit-member-form"><label>Логин<input name="login" autocomplete="username" required maxlength="32"></label><label>Пароль<input type="password" name="password" autocomplete="current-password" required maxlength="128"></label><button type="submit">Войти</button><span id="afit-member-status" role="status"></span></form></div><p id="afit-quota" role="status"></p>'
root=Path('/opt/alenafit-assistant')
page=Path('/var/www/alenafit-assistant/index.html')
backend=root/'server.py'
state=root/'state';state.mkdir(mode=0o700,exist_ok=True)
config=state/'afit_access.json'
source=page.read_text();server=backend.read_text()
# Remove only a prior installation of this same gate.
server=re.sub(r'^# AFIT_ACCESS_GATE_V1.*?^# AFIT_ACCESS_GATE_END\n?', '', server, flags=re.M|re.S)
tree=ast.parse(server)
launches=[n for n in tree.body if isinstance(n,ast.Expr) and isinstance(n.value,ast.Call) and isinstance(n.value.func,ast.Attribute) and n.value.func.attr=='serve_forever']
assert len(launches)==1, 'Unexpected server entry point; nothing changed'
lines=server.splitlines(keepends=True);lines.insert(launches[0].lineno-1,GATE+'\n')
server=''.join(lines);ast.parse(server)
if '// AFIT_MEMBER_UI_V1' not in source:
    old="  if(response.status===401)throw Error('Вход истёк. Обновите страницу и войдите снова.');"
    assert source.count(old)==1, 'Unexpected chat handler; nothing changed'
    source=source.replace(old,"  if(response.status===401){input.value=message;await refreshAccess();throw Error('Для продолжения войдите как участник ALENAFIT.');}")
    assert source.count('  button.disabled=false;')==1, 'Unexpected chat controls; nothing changed'
    source=source.replace('  button.disabled=false;','  button.disabled=false;\n  await refreshAccess();',1)
    assert '<form id="form">' in source, 'Chat form not found; nothing changed'
    source=source.replace('<form id="form">',MEMBER_PANEL+'\n<form id="form">',1)
    # Append after the existing declarations and event handlers.
    at=source.rfind('</script>');assert at!=-1
    source=source[:at]+MEMBER_JS+'\n'+source[at:]
source=re.sub(r'<style id="afit-member-composer">.*?</style>', '', source, flags=re.S)
source=source.replace('<main>',MEMBER_CSS+'\n<main>',1)
if config.exists():
    data=json.loads(config.read_text())
    assert all(k in data for k in ['salt','password_hash','secret']), 'Invalid access configuration'
else:
    password=getpass.getpass('Общий пароль участников ALENAFIT (не отображается): ')
    again=getpass.getpass('Повторите пароль: ')
    assert password==again and 10<=len(password)<=128, 'Passwords differ or password shorter than 10 characters'
    salt=secrets.token_bytes(16)
    data={'salt':salt.hex(),'password_hash':hashlib.pbkdf2_hmac('sha256',password.encode(),salt,260000).hex(),'secret':secrets.token_hex(32)}
    del password,again
stamp=datetime.now().strftime('%Y%m%d-%H%M%S')
for p in (page,backend):shutil.copy2(p,p.with_name(p.name+'.before-members-'+stamp))
fd=os.open(config,os.O_WRONLY|os.O_CREAT|os.O_TRUNC,0o600)
with os.fdopen(fd,'w') as f:json.dump(data,f)
os.chmod(config,0o600)
page.write_text(source);backend.write_text(server)
subprocess.run(['docker','restart','alenafit-assistant-test'],check=True)
print('Готово: компактная отправка, 30 запросов без входа, затем доступ участника. Обновите сайт.')
